create database Retail_Sales;
Use Retail_Sales;

select * from retail_sales_dataset;

-- What is the Total Revenue Generated by the company?

SELECT 
    SUM(`Total Amount`) AS Total_Revenue
FROM
    retail_sales_dataset;


-- How many Transections were recorded?

SELECT 
    COUNT(`Transaction ID`) Total_Transection
FROM
    retail_sales_dataset;
    
-- How many Products were sold in total?

SELECT 
    SUM(Quantity) Total_Product_Sales
FROM
    retail_sales_dataset;
    
-- What is the average transection value?

SELECT 
    AVG(`Total Amount`) Average
FROM
    retail_sales_dataset;


-- What is the highest value transection?

SELECT 
    MAX(`Total Amount`) Highest_Value_Transection
FROM
    retail_sales_dataset;
    
-- What is the lowest value transection?

SELECT 
    MIN(`Total Amount`) Lowest_Value_Transection
FROM
    retail_sales_dataset;
    
-- What is the average quantity of products purchased per transaction?

SELECT 
    AVG(Quantity) Average_Quantity_Per_Transection
FROM
    retail_sales_dataset;
    
-- Which transections generated revenue above the overall average transaction value?

SELECT 
    `Transaction ID`, `Total Amount`
FROM
    retail_sales_dataset
WHERE
    `Total Amount` > (SELECT 
            AVG(`Total Amount`)
        FROM
            retail_sales_dataset);
            

--  How many transections Generated Revenue below 500

SELECT 
    COUNT(`Transaction ID`) Transection_Below_500
FROM
    retail_sales_dataset
WHERE
    `Total Amount` < 500;


